/**
 * Level Patcher & Fairness Validator
 * Ensures that Kaizo mutations generated by Gemma 4 remain mathematically beatable.
 */

export interface Mutation {
  type: 'KAIZO_BLOCK' | 'CRUMBLING_FLOOR' | 'FALLING_SPIKE' | 'CEILING_SPIKE' | 'DECEPTIVE_COIN' | 'BOUNCE_TRAP' | 'ENEMY_AMBUSH';
  x: number; // tile coordinate
  y: number; // tile coordinate
  justification: string;
}

export interface LevelMap {
  width: number;
  height: number;
  tiles: number[][]; // 0: empty, 1: solid, 2: question, 3: spike, 4: crumbling, 5: spring, 6: checkpoint, 7: flag, 8: kaizo (invisible solid)
  enemies: Array<{ type: string; x: number; y: number }>;
  coins: Array<{ x: number; y: number }>;
}

export class LevelPatcher {
  /**
   * Applies mutations with safety guards to preserve solvability.
   */
  static applyMutations(level: LevelMap, mutations: Mutation[]): { level: LevelMap; accepted: Mutation[]; rejected: Mutation[] } {
    const accepted: Mutation[] = [];
    const rejected: Mutation[] = [];

    // Clone level
    const newTiles = level.tiles.map(row => [...row]);
    const newEnemies = [...level.enemies];
    const newCoins = [...level.coins];

    for (const m of mutations) {
      const tx = Math.floor(m.x);
      const ty = Math.floor(m.y);

      // Boundary check
      if (tx < 2 || tx >= level.width - 4 || ty < 2 || ty >= level.height - 2) {
        rejected.push({ ...m, justification: `${m.justification} (Rejected: Out of bounds)` });
        continue;
      }

      // Never block the starting spawn area (x < 5) or the flagpole zone (x > width - 5)
      if (tx < 5 || tx > level.width - 5) {
        rejected.push({ ...m, justification: `${m.justification} (Rejected: Preserving spawn/flag zones)` });
        continue;
      }

      // Check mutation validity
      let valid = false;

      switch (m.type) {
        case 'KAIZO_BLOCK':
          // Invisible block: must be in empty air space
          if (newTiles[ty][tx] === 0) {
            // Ensure there is at least 1 tile of clearance to jump under or over
            const spaceUnder = ty + 1 < level.height && newTiles[ty + 1][tx] === 0;
            const spaceOver = ty - 1 >= 0 && newTiles[ty - 1][tx] === 0;
            if (spaceUnder || spaceOver) {
              newTiles[ty][tx] = 8; // 8 = Kaizo block
              valid = true;
            }
          }
          break;

        case 'CRUMBLING_FLOOR':
          // Only mutate the exposed top surface of a platform. Replacing a
          // wall face creates a visually floating gray tile and is not a
          // meaningful floor adaptation.
          if (newTiles[ty][tx] === 1 &&
              ty > 0 && newTiles[ty - 1][tx] === 0 &&
              ty + 1 < level.height && newTiles[ty + 1][tx] === 1) {
            newTiles[ty][tx] = 4; // 4 = Crumbling block
            valid = true;
          }
          break;

        case 'FALLING_SPIKE':
        case 'CEILING_SPIKE':
          // Must attach to solid ceiling or float overhead
          if (newTiles[ty][tx] === 0 && (ty === 0 || newTiles[ty - 1][tx] === 1 || newTiles[ty - 1][tx] === 8)) {
            newTiles[ty][tx] = 3; // 3 = Spike
            valid = true;
          }
          break;

        case 'DECEPTIVE_COIN':
          // Place coin right above a spike or in a tricky arc
          if (newTiles[ty][tx] === 0) {
            newCoins.push({ x: tx, y: ty });
            valid = true;
          }
          break;

        case 'BOUNCE_TRAP':
          // Replace floor block with high-velocity trampoline that launches player into hazards
          if (newTiles[ty][tx] === 1 &&
              ty > 0 && newTiles[ty - 1][tx] === 0 &&
              ty + 1 < level.height && newTiles[ty + 1][tx] === 1) {
            newTiles[ty][tx] = 5; // 5 = Spring
            valid = true;
          }
          break;

        case 'ENEMY_AMBUSH':
          // Spawn enemy on ground
          if (newTiles[ty][tx] === 0 && ty + 1 < level.height && newTiles[ty + 1][tx] === 1) {
            newEnemies.push({ type: 'gloomba', x: tx * 32, y: ty * 32 });
            valid = true;
          }
          break;
      }

      if (valid) {
        accepted.push(m);
      } else {
        rejected.push(m);
      }
    }

    return {
      level: {
        width: level.width,
        height: level.height,
        tiles: newTiles,
        enemies: newEnemies,
        coins: newCoins
      },
      accepted,
      rejected
    };
  }
}
